Unary & Prefix Operators:
class Vector2D(val x: Double, val y: Double):
  def unary_- : Vector2D = Vector2D(-x, -y)
  def unary_! : Double = math.sqrt(x*x + y*y)

val v = Vector2D(3, 4)
