Operator Overloading:
case class Complex(real: Double, imag: Double):
  def +(that: Complex) = Complex(real + that.real, imag + that.imag)
  def *(that: Complex) = Complex(real*that.real - imag*that.imag, real*that.imag + imag*that.real)
  def unary_- = Complex(-real, -imag)
  def magnitude = math.sqrt(real*real + imag*imag)

val a = Complex(1, 2)
val b = Complex(3, 4)
val sum = a + b      // Complex(4, 6)
val product = a * b  // Complex(-5, 10)

