Tail Recursion:
import scala.annotation.tailrec

@tailrec
def factorial(n: Int, acc: Int = 1): Int = {
  if (n <= 1) acc
  else factorial(n - 1, n * acc)
}

println(factorial(5))  // 120
println(factorial(10000))  // no stack overflow

